using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
namespace LWS.TruckBeerPong.Editor {
public static class PongModels {
 public const string Folder="TruckBeerPong";
 public static Mesh Save(string name,Vector3[] vertices,int[] triangles,Vector2[] uv=null){string path="Assets/"+Folder+"/Models/"+name+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name=name};AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=vertices;mesh.triangles=triangles;mesh.uv=uv??vertices.Select(p=>new Vector2(p.x,p.z)).ToArray();mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);return mesh;}
 // Continuous open-top shell, rolled lip, white hollow interior and sealed
 // bottom. One static nonconvex collision mesh, never a solid cylinder.
 public static Mesh Cup(){Vector2[] profile={new Vector2(1.45f,0),new Vector2(1.62f,.12f),new Vector2(1.67f,.25f),new Vector2(1.65f,.32f),new Vector2(1.86f,1.25f),new Vector2(1.92f,1.3f),new Vector2(1.9f,1.37f),new Vector2(2.12f,2.45f),new Vector2(2.18f,2.5f),new Vector2(2.16f,2.57f),new Vector2(2.34f,3.36f),new Vector2(2.41f,3.45f),new Vector2(2.41f,3.55f),new Vector2(2.2f,3.55f),new Vector2(2.16f,3.35f),new Vector2(1.4f,.25f),new Vector2(0,.25f),new Vector2(0,0),new Vector2(1.45f,0)};const int sides=64;var vertices=new List<Vector3>();var uv=new List<Vector2>();var outside=new List<int>();var inside=new List<int>();for(int ring=0;ring<profile.Length;ring++)for(int i=0;i<=sides;i++){float a=i*Mathf.PI*2/sides;vertices.Add(new Vector3(Mathf.Cos(a)*profile[ring].x,profile[ring].y,Mathf.Sin(a)*profile[ring].x));uv.Add(new Vector2(i/(float)sides,profile[ring].y/3.55f));if(ring<profile.Length-1&&i<sides){int n=ring*(sides+1)+i,b=n+sides+1;(ring>=11?inside:outside).AddRange(new[]{n,b,n+1,n+1,b,b+1});}}var mesh=Save("Hollow rolled-lip red party cup",vertices.ToArray(),outside.Concat(inside).ToArray(),uv.ToArray());mesh.subMeshCount=2;mesh.SetTriangles(outside,0);mesh.SetTriangles(inside,1);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);return mesh;}
 public static Mesh Liquid(){const int n=64;var vertices=new Vector3[n+2];var uv=new Vector2[n+2];var triangles=new int[n*3];uv[0]=Vector2.one*.5f;for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;vertices[i+1]=new Vector3(Mathf.Sin(a)*1.75f,0,Mathf.Cos(a)*1.75f);uv[i+1]=new Vector2(Mathf.Sin(a),Mathf.Cos(a))*.5f+Vector2.one*.5f;if(i<n){triangles[i*3]=0;triangles[i*3+1]=i+1;triangles[i*3+2]=i+2;}}return Save("Recessed beer surface",vertices,triangles,uv);}
 public static Mesh Coil(){const int sections=144,sides=8;var vertices=new List<Vector3>();var triangles=new List<int>();var uv=new List<Vector2>();for(int i=0;i<=sections;i++){float a=i*7*Mathf.PI*2/sections;var center=new Vector3(Mathf.Cos(a)*.9f,i/(float)sections*.55f,Mathf.Sin(a)*.9f);for(int n=0;n<=sides;n++){float b=n*Mathf.PI*2/sides;vertices.Add(center+new Vector3(Mathf.Cos(a)*Mathf.Cos(b)*.075f,Mathf.Sin(b)*.075f,Mathf.Sin(a)*Mathf.Cos(b)*.075f));uv.Add(new Vector2(i/(float)sections,n/(float)sides));if(i<sections&&n<sides){int x=i*(sides+1)+n,y=x+sides+1;triangles.AddRange(new[]{x,x+1,y,x+1,y+1,y});}}}return Save("Seven-turn visible launch spring",vertices.ToArray(),triangles.ToArray(),uv.ToArray());}
 public static GameObject Part(Transform parent,string name,Mesh mesh,Material[] materials){var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterials=materials;return g;}
 public static Vector3 CupPosition(int team,int index){int row=0,start=0;while(index>=start+row+1){start+=row+1;row++;}int col=index-start;float sign=team==0?-1:1;return new Vector3((col-row*.5f)*5.05f,4,sign*(22+row*4.55f));}
}
}
